import gzip,pandas as pd
def meta(f):
    rows={}
    for l in gzip.open(f'studies/data/raw/{f}_series_matrix.txt.gz','rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_') or l.startswith('!Series_'):
            p=l.rstrip('\n').split('\t'); k=p[0]
            while k in rows: k+='_'
            rows[k]=[x.strip('"') for x in p[1:]]
    return rows
